#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char *p;

static void skip(void) {
    while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n' || *p == ',') p++;
}

static int read_int(void) {
    skip();
    int x = 0;
    while (*p >= '0' && *p <= '9') {
        x = x * 10 + (*p - '0');
        p++;
    }
    return x;
}

static int *read_array(int *size) {
    skip();
    if (*p == '[') p++;
    int cap = 8, n = 0;
    int *a = (int *)malloc(cap * sizeof(int));
    while (1) {
        skip();
        if (*p == ']') { p++; break; }
        if (n == cap) {
            cap *= 2;
            a = (int *)realloc(a, cap * sizeof(int));
        }
        a[n++] = read_int();
        skip();
    }
    *size = n;
    return a;
}

static int **read_matrix(int *rows, int **cols) {
    skip();
    if (*p == '[') p++;
    int rcap = 16, r = 0;
    int **m = (int **)malloc(rcap * sizeof(int *));
    int *c = (int *)malloc(rcap * sizeof(int));
    while (1) {
        skip();
        if (*p == ']') { p++; break; }
        if (r == rcap) {
            rcap *= 2;
            m = (int **)realloc(m, rcap * sizeof(int *));
            c = (int *)realloc(c, rcap * sizeof(int));
        }
        int sz = 0;
        m[r] = read_array(&sz);
        c[r] = sz;
        r++;
        skip();
    }
    *rows = r;
    *cols = c;
    return m;
}

static int n_global;
static int *price_global;
static int **special_global;
static int special_count;
static int *special_cols;
static int *memo;
static int *seen;

static int encode_state(const int *needs) {
    int key = 0, mul = 1;
    for (int i = 0; i < n_global; ++i) {
        key += needs[i] * mul;
        mul *= 11;
    }
    return key;
}

static int dfs(const int *needs) {
    int key = encode_state(needs);
    if (seen[key]) return memo[key];

    int best = 0;
    for (int i = 0; i < n_global; ++i) best += price_global[i] * needs[i];

    for (int s = 0; s < special_count; ++s) {
        int next[6];
        int usable = 1;
        for (int i = 0; i < n_global; ++i) {
            next[i] = needs[i] - special_global[s][i];
            if (next[i] < 0) { usable = 0; break; }
        }
        if (usable) {
            int candidate = special_global[s][n_global] + dfs(next);
            if (candidate < best) best = candidate;
        }
    }

    seen[key] = 1;
    memo[key] = best;
    return best;
}

int shoppingOffers(int *price, int priceSize, int **special, int specialSize,
                   int *specialColSize, int *needs, int needsSize) {
    n_global = priceSize;
    price_global = price;
    special_global = special;
    special_count = specialSize;
    special_cols = specialColSize;
    (void)special_cols;
    (void)needsSize;

    int states = 1;
    for (int i = 0; i < n_global; ++i) states *= 11;
    memo = (int *)calloc(states, sizeof(int));
    seen = (int *)calloc(states, sizeof(int));

    int result = dfs(needs);
    free(memo);
    free(seen);
    return result;
}

