class Solution {
    vector<int> price;
    vector<vector<int>> special;
    unordered_map<string, int> memo;

    string key(const vector<int>& needs) {
        string s;
        for (int x : needs) {
            s += to_string(x);
            s += '#';
        }
        return s;
    }

    int dfs(const vector<int>& needs) {
        string k = key(needs);
        auto it = memo.find(k);
        if (it != memo.end()) return it->second;

        int n = price.size();
        int best = 0;
        for (int i = 0; i < n; ++i) best += price[i] * needs[i];

        for (const auto& offer : special) {
            vector<int> next(n);
            bool usable = true;
            for (int i = 0; i < n; ++i) {
                next[i] = needs[i] - offer[i];
                if (next[i] < 0) {
                    usable = false;
                    break;
                }
            }
            if (usable) best = min(best, offer[n] + dfs(next));
        }

        memo[k] = best;
        return best;
    }

public:
    int shoppingOffers(vector<int>& price_, vector<vector<int>>& special_, vector<int>& needs) {
        price = price_;
        special.clear();
        for (const auto& offer : special_) {
            bool nonEmpty = false;
            for (int i = 0; i < (int)price.size(); ++i) {
                if (offer[i] != 0) { nonEmpty = true; break; }
            }
            if (nonEmpty) special.push_back(offer);
        }
        memo.clear();
        return dfs(needs);
    }
};

