class Solution {
    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        int n = price.size();
        List<List<Integer>> offers = new ArrayList<>();
        for (List<Integer> offer : special) {
            boolean nonEmpty = false;
            for (int i = 0; i < n; i++) if (offer.get(i) != 0) { nonEmpty = true; break; }
            if (nonEmpty) offers.add(offer);
        }
        Map<String, Integer> memo = new HashMap<>();
        return dfs(price, offers, needs, memo);
    }

    private int dfs(List<Integer> price, List<List<Integer>> offers, List<Integer> needs, Map<String, Integer> memo) {
        String key = needs.toString();
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int n = price.size();
        int best = 0;
        for (int i = 0; i < n; i++) best += price.get(i) * needs.get(i);

        for (List<Integer> offer : offers) {
            List<Integer> next = new ArrayList<>(n);
            boolean usable = true;
            for (int i = 0; i < n; i++) {
                int remain = needs.get(i) - offer.get(i);
                if (remain < 0) { usable = false; break; }
                next.add(remain);
            }
            if (usable) best = Math.min(best, offer.get(n) + dfs(price, offers, next, memo));
        }

        memo.put(key, best);
        return best;
    }
}

