from typing import List
from functools import lru_cache

class Solution:
    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:
        n = len(price)
        offers = [offer for offer in special if any(offer[i] for i in range(n))]

        @lru_cache(maxsize=None)
        def dfs(state):
            best = sum(price[i] * state[i] for i in range(n))
            for offer in offers:
                next_state = []
                usable = True
                for i in range(n):
                    remain = state[i] - offer[i]
                    if remain < 0:
                        usable = False
                        break
                    next_state.append(remain)
                if usable:
                    best = min(best, offer[n] + dfs(tuple(next_state)))
            return best

        return dfs(tuple(needs))

