static vector<string> splitTop(const string& s) {
    vector<string> parts;
    int depth = 0, start = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        if (s[i] == '[') ++depth;
        else if (s[i] == ']') --depth;
        else if (s[i] == ',' && depth == 0) {
