public class Main {
    static List<String> splitTop(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        if (start < s.length()) parts.add(s.substring(start).trim());
        return parts;
    }

    static List<Integer> parseIntList(String s) {
        s = s.trim();
        if (s.equals("[]")) return new ArrayList<>();
        String inner = s.substring(1, s.length() - 1).trim();
        List<Integer> result = new ArrayList<>();
        if (inner.isEmpty()) return result;
        for (String part : inner.split(",")) result.add(Integer.parseInt(part.trim()));
        return result;
    }

    static List<List<Integer>> parseSpecial(String s) {
        s = s.trim();
        if (s.equals("[]")) return new ArrayList<>();
        String inner = s.substring(1, s.length() - 1).trim();
        List<List<Integer>> result = new ArrayList<>();
        for (String row : splitTop(inner)) result.add(parseIntList(row));
        return result;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        String outer = line.substring(1, line.length() - 1);
        List<String> parts = splitTop(outer);
        List<Integer> price = parseIntList(parts.get(0));
        List<List<Integer>> special = parseSpecial(parts.get(1));
        List<Integer> needs = parseIntList(parts.get(2));
        System.out.println(new Solution().shoppingOffers(price, special, needs));
    }
}

